import sys

def main():
    data = sys.stdin.read().split()
    n, d = int(data[0]), int(data[1])
    w = [int(x) for x in data[2:2 + n]]
    lo, hi = max(w), sum(w)
    while lo < hi:
        mid = (lo + hi) // 2
        trips, cur = 1, 0
        for x in w:
            if cur + x > mid:
                trips += 1
                cur = 0
            cur += x
        if trips <= d:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

