    def fmt(d, w):
        return f'{len(w)} {d}\n' + ' '.join(map(str, w))
    tests = [fmt(1, [5]), fmt(1, [1, 2, 3]), fmt(3, [4, 4, 4]), fmt(2, [10, 1, 1, 10]), fmt(2, [1, 4, 7, 5]),
             fmt(3, [1, 4, 7, 5]), fmt(2, [100, 1]), fmt(1, [10**9, 10**9])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            d = rng.randint(1, n)
            tests.append(fmt(d, [rng.randint(1, rng.choice([5, 30, 100])) for _ in range(n)]))
    N = 100000
    tests.append(fmt(rng.randint(1, N), [rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt(1, [10**9] * N))
    tests.append(fmt(N, [rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt(1234, [rng.randint(1, 1000) for _ in range(N)]))
    return tests

